import{_ as r,C as s,o as n,c as d,a3 as a,E as e}from"./chunks/framework.CZBGEXos.js";const b=JSON.parse('{"title":"Шар мажорів","description":"","frontmatter":{},"headers":[],"relativePath":"uk/customize/majors.md","filePath":"uk/customize/majors.md"}'),l={name:"uk/customize/majors.md"};function i(c,t,h,p,u,m){const o=s("Screenshot");return n(),d("div",null,[t[0]||(t[0]=a('<h1 id="шар-мажорів" tabindex="-1">Шар мажорів <a class="header-anchor" href="#шар-мажорів" aria-label="Permalink to &quot;Шар мажорів&quot;">​</a></h1><p>Шар мажорів малює три види значної ринкової активності прямо на графіку — кожен за тією ціною, за якою він відбувся:</p><table tabindex="0"><thead><tr><th>Шар</th><th>Що позначає</th></tr></thead><tbody><tr><td><strong>Major trades</strong></td><td>Окремі угоди з верхніх 10% за розміром для цього тікера</td></tr><tr><td><strong>Clusters</strong></td><td>Однохвилинні цінові рівні, які поглинули значно більше обсягу, ніж звичайний рівень на цій монеті</td></tr><tr><td><strong>Liquidations</strong></td><td>Примусові закриття позицій від $5 000</td></tr></tbody></table>',3)),e(o,{src:"majors.jpg",alt:"Графік із шаром мажорів: трикутники угод і комірка кластера",caption:"Мажори на 5хв графіку — трикутники угод і одна комірка кластера"}),t[1]||(t[1]=a('<p>Це допоміжний інструмент для читання графіка, а не сканер: він показує, <strong>де</strong> пройшов великий обсяг на графіку, який ви й так дивитесь.</p><h2 id="як-увімкнути" tabindex="-1">Як увімкнути <a class="header-anchor" href="#як-увімкнути" aria-label="Permalink to &quot;Як увімкнути&quot;">​</a></h2><p>Шар вмикається <strong>для кожного графіка окремо</strong>, не глобально. Кожен графік має <strong>кнопку мажорів</strong> на панелі інструментів, а стрілочка поруч відкриває меню шарів.</p><p>Також можна натиснути клавішу шару — за замовчуванням <strong><kbd>M</kbd></strong> — тримаючи курсор над графіком. Клавіша змінюється у вкладці <strong>Home</strong> як <strong>Majors overlay key</strong>, поруч із клавішами інструментів рисування.</p><table tabindex="0"><thead><tr><th>Інструмент</th><th>Де доступний шар</th></tr></thead><tbody><tr><td><a href="/manual/uk/tools/analyzer.html">Analyzer</a></td><td>Кожна панель графіка і повний екран</td></tr><tr><td><a href="/manual/uk/tools/knives.html">Knives</a></td><td>Лише повний екран</td></tr><tr><td><a href="/manual/uk/tools/monitor.html">Monitor</a></td><td>Лише повний екран</td></tr></tbody></table><p>У Knives і Monitor він навмисно обмежений повним екраном — картка тікера занадто мала, щоб маркери за цінами можна було прочитати.</p><div class="info custom-block"><p class="custom-block-title">Якщо зняти всі три шари, оверлей вимикається</p><p>Коли ви вимикаєте всі три шари, вимикається і сам оверлей, замість того щоб лишатися увімкненим і не малювати нічого. Тож кнопки завжди відповідають тому, що ви реально бачите. Повторне увімкнення повертає всі три шари.</p></div><h2 id="як-читати-маркери" tabindex="-1">Як читати маркери <a class="header-anchor" href="#як-читати-маркери" aria-label="Permalink to &quot;Як читати маркери&quot;">​</a></h2><h3 id="великі-угоди-—-трикутники" tabindex="-1">Великі угоди — трикутники <a class="header-anchor" href="#великі-угоди-—-трикутники" aria-label="Permalink to &quot;Великі угоди — трикутники&quot;">​</a></h3><p>Трикутник вказує <strong>у той бік, куди штовхав агресор</strong>: вгору і зеленим для покупки, вниз і червоним для продажу. Розмір залежить від доларової величини угоди відносно найбільшої на екрані, тож найбільший принт у полі зору завжди має найбільший трикутник.</p><p>При наведенні видно сторону, розмір у доларах, ціну, перцентиль, біржу й час.</p><div class="info custom-block"><p class="custom-block-title">Що означає перцентиль</p><p>Кожна угода несе перцентиль, який вона мала <strong>в момент виконання</strong>. Пороги перераховуються для кожного тікера за ковзним 4-годинним вікном, тож <code>p99</code> означає, що угода була у верхньому 1% <em>саме тоді</em>, а не відносно сьогодні.</p></div><h3 id="кластери-—-залиті-комірки" tabindex="-1">Кластери — залиті комірки <a class="header-anchor" href="#кластери-—-залиті-комірки" aria-label="Permalink to &quot;Кластери — залиті комірки&quot;">​</a></h3><p>Кластер — це однохвилинний ціновий рівень, який утримав значно більше обсягу, ніж звичайний рівень на цій монеті. Малюється залитою коміркою за тією ціною, з обсягом усередині.</p><ul><li><strong>Колір</strong> — домінуюча сторона: зелений, якщо покупки переважили продажі, інакше червоний.</li><li><strong>Число</strong> — обсяг саме домінуючої сторони, а не дельта.</li><li><strong>Прозорість</strong> — відносно найгучнішого рівня <em>серед видимих зараз</em>, тож шкала перенормовується при зумі, а не сплющується через одного гіганта за екраном.</li></ul><p>При наведенні видно загальний обсяг, покупки, продажі, дельту і розподіл споту, якщо спотовий обсяг є.</p><div class="warning custom-block"><p class="custom-block-title">«no clusters — price too stable» — це не помилка</p><p>Рівні мають ширину близько 0.05% — приблизно $55 на BTC. Спокійна хвилина BTC не проходить такої відстані, тож уся хвилина вміщується в один рівень, і жоден не може виділитися на тлі сусідів.</p><p>На дуже стабільних і дорогих монетах кластерів може не бути <strong>взагалі</strong>. Оверлей пише про це в рядку стану, замість того щоб виглядати зламаним на найпопулярнішому тікері з усіх.</p></div><h3 id="ліквідаціі-—-ромби" tabindex="-1">Ліквідації — ромби <a class="header-anchor" href="#ліквідаціі-—-ромби" aria-label="Permalink to &quot;Ліквідації — ромби&quot;">​</a></h3><p>Ромб позначає примусове закриття позиції, розмір залежить від суми.</p><p><strong>Колір відповідає тиску, а не слову.</strong> Ліквідований <em>лонг</em> — це примусовий <em>продаж</em>, тож малюється червоним і вниз; ліквідований <em>шорт</em> — це примусова покупка, малюється зеленим. Це найлегше сплутати, і саме так це працює у стрічці ліквідацій у вікні Alerts.</p><p>При наведенні написано словами — <code>long closed → forced sell</code> — а також розмір, ціна, біржа й час.</p><h2 id="рядок-стану" tabindex="-1">Рядок стану <a class="header-anchor" href="#рядок-стану" aria-label="Permalink to &quot;Рядок стану&quot;">​</a></h2><p>Оверлей пише один рядок над графіком. Він навмисно чесно повідомляє про кожне обмеження, замість того щоб мовчки показувати неповну картину:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MAJORS · binance+bybit · top 25 of 29k trades</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Фрагмент</th><th>Значення</th></tr></thead><tbody><tr><td><code>MAJORS · binance+bybit</code></td><td>Маркери завжди з Binance і Bybit, з якої б біржі не були свічки</td></tr><tr><td><code>candles &lt;біржа&gt;</code></td><td>Показується, коли свічки з іншої біржі, ніж маркери</td></tr><tr><td><code>candles spot</code></td><td>Показується, коли ви дивитесь спотовий графік</td></tr><tr><td><code>top N of M trades</code></td><td><strong>У вікні було M, намальовано лише найбільших N</strong> — див. <a href="#markers-drawn">Markers drawn</a></td></tr><tr><td><code>no clusters — price too stable</code></td><td>Пояснено вище</td></tr><tr><td><code>14d max</code></td><td>Таймфрейм сягає далі, ніж сервер зберігає дані</td></tr><tr><td><code>connecting…</code> / <code>feed error</code> / <code>no data for this symbol</code></td><td>Стан підключення</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Маркери лише з Binance і Bybit</p><p>Потік охоплює безстрокові USDT/USDC контракти Binance і Bybit. Якщо ви дивитесь графік Gate.io, OKX чи Hyperliquid — свічки будуть тієї біржі, а маркери ні, і рядок стану про це скаже. Warden ніколи не приховує це мовчки.</p></div><p>Історія сягає <strong>14 днів</strong>. На таймфреймі, ширшому за це, ліва частина графіка просто не має маркерів, а в рядку зʼявляється <code>14d max</code>.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2>',28)),e(o,{src:"majors-settings.jpg",alt:"Налаштування шару мажорів у вкладці Home",caption:"Home → Majors overlay"}),t[2]||(t[2]=a('<p>Три фільтри розташовані у вкладці <strong>Home</strong>, у секції <strong>Majors overlay</strong>. Вони діють на всі графіки в усіх інструментах.</p><h3 id="markers-drawn" tabindex="-1">Markers drawn <a class="header-anchor" href="#markers-drawn" aria-label="Permalink to &quot;Markers drawn&quot;">​</a></h3><p>Скільки найбільших малювати, <strong>окремо для кожного типу</strong>. Діапазон <strong>від 25 до 1500</strong> з кроком 25, за замовчуванням 200.</p><p>Це контроль саме для <strong>угод</strong>. У завантаженому вікні їх тисячі, тож на графік потрапляють лише найбільші — і рядок стану повідомляє, коли таке обрізання сталося.</p><p>Для кластерів і ліквідацій це рідко має значення: їх зазвичай значно менше за ліміт, тож реально вирішують їхні пороги розміру нижче.</p><h3 id="cluster-strength" tabindex="-1">Cluster strength <a class="header-anchor" href="#cluster-strength" aria-label="Permalink to &quot;Cluster strength&quot;">​</a></h3><p>Ховає цінові рівні, які тримають менше, ніж стільки обсягів звичайного рівня на цій монеті. Діапазон <strong>від 3× до 25×</strong> з кроком 0.5, за замовчуванням 3×.</p><ul><li><strong>3×</strong> — усе, що зберігає сервер, найм&#39;якше можливе значення.</li><li><strong>6×</strong> — лише виразно сильні рівні.</li></ul><p>Підняти це — найшвидший спосіб заспокоїти галасливий графік, не втративши важливих рівнів.</p><h3 id="liquidation-size" tabindex="-1">Liquidation size <a class="header-anchor" href="#liquidation-size" aria-label="Permalink to &quot;Liquidation size&quot;">​</a></h3><p>Ховає ліквідації, менші за цю суму. Діапазон <strong>від $5 000 до $1 000 000</strong> з кроком $5 000, за замовчуванням $5 000.</p><p>$5 000 — це власний поріг сервера: меншого він не зберігає взагалі, тож мінімальне значення вже означає «геть усе, що є».</p><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/customize/chart-colors.html">Графіки та рисування</a> — кольори свічок, інструменти рисування і клавіші, поруч із якими живе клавіша оверлея</li><li><a href="/manual/uk/tools/analyzer.html">Analyzer</a> — інструмент, де оверлей доступний на кожній панелі</li></ul>',14))])}const k=r(l,[["render",i]]);export{b as __pageData,k as default};
